    # exactly the six media-codec axes -- and on 1.42.2 those six are UNKNOWN fields, so a
    # listing filtered on one answers EVERY row (3887 of zen's 3887) and /query/parse
    # reports an `Error` rather than a `Rule`. plexsim advertised all six in the smart
    # filter builder, filtered on them (0 rows) and parsed them as real Rules.
    meta_c17d1 = get(base, "/library/sections/%s/all?includeMeta=1"
                     "&X-Plex-Container-Start=0&X-Plex-Container-Size=0"
                     % movie_section)[1].get("Meta") or {}
    movie_fields_c17d1 = []
    for t_c17d1 in meta_c17d1.get("Type") or []:
        if t_c17d1.get("type") == "movie":
            movie_fields_c17d1 = [f_c17d1.get("key")
                                  for f_c17d1 in (t_c17d1.get("Field") or [])]
    ep_fields_c17d1 = []
    if show_section:
        smeta_c17d1 = get(base, "/library/sections/%s/all?includeMeta=1&type=4"
                                "&X-Plex-Container-Start=0&X-Plex-Container-Size=0" % show_section)[1].get("Meta") or {}
        for t_c17d1 in smeta_c17d1.get("Type") or []:
            if t_c17d1.get("type") == "episode":
                ep_fields_c17d1 = [f_c17d1.get("key")
                                   for f_c17d1 in (t_c17d1.get("Field") or [])]
    codecs_c17d1 = ("hdr10plus", "atmos", "videoCodec", "audioCodec", "subtitleCodec",
                    "audioLayout")
    advertised_c17d1 = [k_c17d1 for k_c17d1 in movie_fields_c17d1 + ep_fields_c17d1
                        if str(k_c17d1).rpartition(".")[2] in codecs_c17d1]
    all_c17d1 = get(base, "/library/sections/%s/all?type=1"
                    "&X-Plex-Container-Start=0&X-Plex-Container-Size=0"
                    % movie_section)[1].get("totalSize")
    filtered_c17d1 = get(base, "/library/sections/%s/all?type=1&videoCodec=h264"
                               "&X-Plex-Container-Start=0&X-Plex-Container-Size=0" % movie_section)[1].get("totalSize")
    # /query/parse answers a root `Query`, not a MediaContainer, so the suite's own
    # get() -- which reads MediaContainer -- hands back an empty dict here.
    parsed_c17d1 = json.loads(request(
        base, "GET", "/library/sections/%s/query/parse?type=1&atmos=1"
        % movie_section)[1]).get("Query") or {}
    check("the Meta Field list is 1.42.2's, not 1.43.4's",
          advertised_c17d1 == [] and len(movie_fields_c17d1) == 34
          and (not show_section or len(ep_fields_c17d1) == 20)
          and filtered_c17d1 == all_c17d1 and all_c17d1
          and bool(parsed_c17d1.get("Error")) and not parsed_c17d1.get("Rule"),
          "movie=%d episode=%d codecs=%s videoCodec=%s/%s parse=%s"
          % (len(movie_fields_c17d1), len(ep_fields_c17d1), advertised_c17d1,
             filtered_c17d1, all_c17d1,
             "Error" if parsed_c17d1.get("Error") else "Rule"))
    empty_codecs_c41a = {
        name_c41a: get(base, "/library/sections/%s/all?type=1&%s="
                       "&X-Plex-Container-Start=0&X-Plex-Container-Size=0"
                       % (movie_section, name_c41a))[1].get("totalSize")
        for name_c41a in ("videoCodec", "audioCodec", "subtitleCodec")}
    check("the removed 1.43 codec fields are ignored even with empty operands",
          all(value_c41a == all_c17d1 for value_c41a in empty_codecs_c41a.values()),
          "%s vs %s" % (empty_codecs_c41a, all_c17d1))


    # Cycle 17, measured on kids (1.43.4) and zen (1.42.2), which agree byte for byte
    # over the whole table: an XML attribute value is escaped as `&` -> `&amp;`,
    # `<` -> `&lt;`, `>` -> `&gt;`, `"` -> `&#34;` and `'` -> `&#39;` (NUMERIC, not
    # `&quot;`/`&apos;`); TAB -> `&#9;` in decimal but NEWLINE and CR -> `&#xA;`/`&#xD;`
    # in HEX; every codepoint from U+0080 up -> its DECIMAL numeric reference, astral
    # plane included (an emoji is `&#128512;`, not a surrogate pair); and every control
    # character XML 1.0 forbids -- U+0001..U+0008, U+000B, U+000C, U+000E..U+001F and
    # U+007F -- is replaced with a literal `?`. So a real PMS's XML is pure ASCII even
    # though it declares UTF-8. plexsim used `xml.sax.saxutils.quoteattr`, which writes
    # `&quot;`, leaves `'` alone, sends `\n`/`\r` as decimal and passes every non-ASCII
    # character through raw -- a different body on every response carrying an accent or
    # an apostrophe, which on a real library is most of them.
    def xml_title2_c17d2(value_c17d2):
        return re.search(r'title2="([^"]*)"', request(
            base, "GET", "/library/sections/%s/firstCharacter/%s"
            % (movie_section, quote(value_c17d2)), want_json=False)[1]
            .decode("utf-8", "replace"))
    cases_c17d2 = [
        ("a<b>c&d", "Start with &#39;a&lt;b&gt;c&amp;d&#39;"),
        ('"', "Start with &#39;&#34;&#39;"),
        ("'", "Start with &#39;&#39;&#39;"),
        ("\t", "Start with &#39;&#9;&#39;"),
        ("\n", "Start with &#39;&#xA;&#39;"),
        ("\r", "Start with &#39;&#xD;&#39;"),
        ("\x7f", "Start with &#39;?&#39;"),
        ("\x0b", "Start with &#39;?&#39;"),
        ("\u00e9", "Start with &#39;&#233;&#39;"),
        ("\u20ac", "Start with &#39;&#8364;&#39;"),
        ("\U0001f600", "Start with &#39;&#128512;&#39;"),
    ]
    wrong_c17d2 = []
    for value_c17d2, want_c17d2 in cases_c17d2:
        found_c17d2 = xml_title2_c17d2(value_c17d2)
        got_c17d2 = found_c17d2.group(1) if found_c17d2 else None
        if got_c17d2 != want_c17d2:
            wrong_c17d2.append((value_c17d2, got_c17d2, want_c17d2))
    body_c17d2 = request(base, "GET", "/library/sections/%s/firstCharacter/%s"
                         % (movie_section, quote("\u00e9")), want_json=False)[1]
    check("XML escapes like a real PMS: numeric refs, ASCII-only body",
          not wrong_c17d2 and all(byte_c17d2 < 128 for byte_c17d2 in body_c17d2),
          "wrong=%s ascii=%s" % (wrong_c17d2[:2],
                                 all(byte_c17d2 < 128 for byte_c17d2 in body_c17d2)))


    # Cycle 17: §3.3 carried "the MECHANISM is measured; the COVERAGE is only as wide as
    # capture_i18n.py's path list" since cycle 16, and it was right. Sweeping 87 paths
    # against kids in German found 119 (attribute, string) pairs the reference
    # translates that the table did not hold, and zen -- 1.42.2, the build plexsim
    # reports -- moves the same families (43 strings on a library's /prefs, 17 on
    # /hubs/search, 2 on /butler). The biggest is the PREFERENCES family: every `label`,
    # `summary` and `enumValues` of the Edit Library dialog and the per-item Advanced
    # pane, none of which was covered. Beside it: the seventeen typed search hubs, whose
    # titles the client lays the page out from; the butler's task titles and
    # descriptions; a GENERATED `Episode N`, the sibling of the `Season N` rule already
    # in the table; and /query/parse's `fieldTitle`. The table is a strict superset of
    # cycle 16's -- 451 entries against 342, nothing dropped. (The ITEM Preferences
    # block needs the next commit as well: the localiser never reached it.)
    def de_c17d3(path_c17d3):
        return request(base, "GET", path_c17d3 + ("&" if "?" in path_c17d3 else "?")
                       + "X-Plex-Language=de")[1].decode("utf-8", "replace")
    prefs_c17d3 = de_c17d3("/library/sections/%s/prefs" % movie_section)
    en_prefs_c17d3 = request(base, "GET", "/library/sections/%s/prefs"
                             % movie_section)[1].decode("utf-8", "replace")
    hubs_c17d3 = de_c17d3("/hubs/search?query=a")
    butler_c17d3 = de_c17d3("/butler")
    check("the translation table covers the prefs, search hub and butler strings",
          "Sammlungen" in prefs_c17d3 and "Collections" in en_prefs_c17d3
          and "Schauspieler" in hubs_c17d3 and "Sammlungen" in hubs_c17d3
          and "Datenbank sichern" in butler_c17d3,
          "prefs=%s hubs=%s butler=%s"
          % ("Sammlungen" in prefs_c17d3, "Schauspieler" in hubs_c17d3,
             "Datenbank sichern" in butler_c17d3))

    # Cycle 41 swept every safe read family from the complete retained client and
    # found four 1.42.2 source strings that the earlier path list never reached.
    # All 28 translations were captured from zen; these stable German witnesses
    # exercise the setting and both per-library hub families through the API.
    prefs_de_c41r3 = get(base, "/:/prefs?X-Plex-Language=de")[1]
    prefs_by_id_c41r3 = {row_c41r3.get("id"): row_c41r3
                         for row_c41r3 in prefs_de_c41r3.get("Setting") or []}
    movie_hubs_de_c41r3 = get(
        base, "/hubs/sections/%s?X-Plex-Container-Size=20&X-Plex-Language=de"
              % movie_section)[1]
    show_hubs_de_c41r3 = get(
        base, "/hubs/sections/%s?X-Plex-Container-Size=20&X-Plex-Language=de"
              % show_section)[1] if show_section else {}
    movie_titles_c41r3 = {hub_c41r3.get("title")
                          for hub_c41r3 in movie_hubs_de_c41r3.get("Hub") or []}
    show_titles_c41r3 = {hub_c41r3.get("title")
                         for hub_c41r3 in show_hubs_de_c41r3.get("Hub") or []}
    check("the cycle 41 prefs and per-library hub strings are localised",
          (prefs_by_id_c41r3.get("TranscoderTempDirectory") or {}).get("summary")
          == "Verzeichnis das während des Transkodierens für temporäre Dateien genutzt wird"
          and "Top-Auswahl ungesehener Filme" in movie_titles_c41r3
          and {"Serie starten", "Bestbewertete Serien"} <= show_titles_c41r3,
          "prefs=%r movie=%s show=%s"
          % ((prefs_by_id_c41r3.get("TranscoderTempDirectory") or {}).get("summary"),
             sorted(movie_titles_c41r3), sorted(show_titles_c41r3)))


    # Cycle 17, mapped path by path on kids by diffing a whole item document against
    # itself in German: inside a `Metadata` row the reference translates exactly three
    # things -- a GENERATED `Season N`/`Episode N` (already implemented), the
    # `Preferences` block's `Setting` rows (`label`, `summary` and `enumValues` alike,
    # at `/library/metadata/{id}?includePreferences=1` on a movie, a show and a season)
    # and a `Stream`'s language fields -- and nothing else: the row's own `title`,
    # `summary` and tag names stay English in every language. plexsim's localiser stops
    # dead at the row boundary, so the whole per-item Advanced pane -- 31 labels, 30
    # summaries and 19 enum lists -- stayed English for every non-English client while
    # the same settings on `/library/sections/{id}/prefs` were translated.
    def de_c17d4(path_c17d4):
        body_c17d4 = request(base, "GET", path_c17d4 + ("&" if "?" in path_c17d4 else "?")
                             + "X-Plex-Language=de")[1]
        return json.loads(body_c17d4)["MediaContainer"]["Metadata"][0]
    show_de_c17d4 = de_c17d4("/library/metadata/%s?includePreferences=1" % show)
    show_en_c17d4 = get(base, "/library/metadata/%s?includePreferences=1"
                        % show)[1]["Metadata"][0]
    settings_c17d4 = {s_c17d4.get("id"): s_c17d4
                      for s_c17d4 in ((show_de_c17d4.get("Preferences") or {})
                                      .get("Setting") or [])}
    english_c17d4 = {s_c17d4.get("id"): s_c17d4
                     for s_c17d4 in ((show_en_c17d4.get("Preferences") or {})
                                     .get("Setting") or [])}
    ordering_c17d4 = settings_c17d4.get("showOrdering") or {}
    flatten_c17d4 = settings_c17d4.get("flattenSeasons") or {}
    check("the localiser reaches a row's Preferences block",
          ordering_c17d4.get("label") == "Reihenfolge Folgen"
          and (english_c17d4.get("showOrdering") or {}).get("label") == "Episode ordering"
          and flatten_c17d4.get("label") == "Staffeln"
          and "Mediathek-Standard" in str(flatten_c17d4.get("enumValues") or "")
          and show_de_c17d4.get("title") == show_en_c17d4.get("title"),
          "ordering=%r flatten=%r enum=%r title-untouched=%s"
          % (ordering_c17d4.get("label"), flatten_c17d4.get("label"),
             str(flatten_c17d4.get("enumValues"))[:30],
             show_de_c17d4.get("title") == show_en_c17d4.get("title")))


    # Cycle 17, measured on kids and held out on zen's real streams in de, fr and es: a
    # Stream's `language` is localised, and its two display titles are COMPOSED from the
    # localised name rather than substituted into. The difference shows on zen's movie
    # 380, whose English subtitle track is TITLED "English": its `displayTitle` moves
    # `English` -> `Englisch` while its `extendedDisplayTitle` stays `English (SRT)`,
    # because the language part was already omitted for carrying one of the title's own
    # words -- the omission is decided on the ENGLISH name and only the rendered name
    # moves. Its Tamil track goes the other way: `Tamil (Tamil-in-Tamil SRT)` becomes
    # `Tamil (Tamoul SRT)` in French. plexsim left every stream field English.
    # The English streams in this fixture are the SHOW's episodes, not the movies.
    rows_c17d5 = list(get(base, "/library/sections/%s/all" % movie_section)[1]
                      .get("Metadata") or [])
    if show:
        rows_c17d5 += (get(base, "/library/metadata/%s/allLeaves" % show)[1]
                       .get("Metadata") or [])
    found_c17d5 = None
    for row_c17d5 in rows_c17d5:
        detail_c17d5 = (get(base, "/library/metadata/%s" % row_c17d5["ratingKey"])[1]
                        .get("Metadata") or [{}])[0]
        for media_c17d5 in detail_c17d5.get("Media") or []:
            for part_c17d5 in media_c17d5.get("Part") or []:
                for stream_c17d5 in part_c17d5.get("Stream") or []:
                    if stream_c17d5.get("language") == "English" and found_c17d5 is None:
                        found_c17d5 = (row_c17d5["ratingKey"], stream_c17d5.get("id"))
    if found_c17d5 is None:
        skip("a Stream's language and titles follow X-Plex-Language",
             "no English stream in the fixture")
    else:
        key_c17d5, stream_id_c17d5 = found_c17d5

        def stream_of_c17d5(lang_c17d5):
            body_c17d5 = request(base, "GET", "/library/metadata/%s%s"
                                 % (key_c17d5, "?X-Plex-Language=" + lang_c17d5
                                    if lang_c17d5 else ""))[1]
            row_c17d5 = json.loads(body_c17d5)["MediaContainer"]["Metadata"][0]
            for media_c17d5 in row_c17d5.get("Media") or []:
                for part_c17d5 in media_c17d5.get("Part") or []:
                    for s_c17d5 in part_c17d5.get("Stream") or []:
                        if s_c17d5.get("id") == stream_id_c17d5:
                            return s_c17d5
            return {}
        en_c17d5 = stream_of_c17d5(None)
        de_c17d5 = stream_of_c17d5("de")
        fr_c17d5 = stream_of_c17d5("fr")
        check("a Stream's language and titles follow X-Plex-Language",
              en_c17d5.get("language") == "English"
              and de_c17d5.get("language") == "Englisch"
              and fr_c17d5.get("language") == "Anglais"
              and str(de_c17d5.get("displayTitle") or "").startswith("Englisch")
              and str(en_c17d5.get("displayTitle") or "").startswith("English")
              and "Englisch" in str(de_c17d5.get("extendedDisplayTitle") or ""),
              "en=%r de=%r/%r fr=%r"
              % (en_c17d5.get("displayTitle"), de_c17d5.get("language"),
                 de_c17d5.get("displayTitle"), fr_c17d5.get("language")))


    # Cycle 17, re-measured by the driver on kids (1.43.4) and zen (1.42.2), which agree:
    # a SHOW's `/allLeaves` -- and no other container -- stamps every episode's
    # `grandparentThumb`, `grandparentArt`, `grandparentTheme` and `art` with the
    # EPISODE's own `addedAt` instead of the show's current artwork version. The
    # episode's detail row, the season's `/children`, the section grid at `type=4`,
    # `recentlyAdded`, `newest`, `/library/all` and the hubs all carry the show's
    # CURRENT stamp; 14 of 14 stamped rows over 140 episodes on zen and 3 of 3 on kids
    # carry their own. It is the same family as the `studio` this container already
    # carries: a property of the list, not of the row. The hunt reported it as a
    # property of an EPISODE row -- it is not, and the section grid disagrees with that
    # reading 641 times on zen.
    #
    # What it costs a client: an episode's grandparent artwork URL on this list is
    # stable for the life of the row, so a client that caches it keeps a valid URL
    # across artwork edits. plexsim re-pointed it at the show's newest version, which
    # invalidates the cached image for every episode of the show on every edit.
    leaves_c17a1 = (get(base, "/library/metadata/%s/allLeaves" % show)[1]
                    .get("Metadata") or [])
    grid_c17a1 = [r_c17a1 for r_c17a1 in (get(
        base, "/library/sections/%s/all?type=4" % show_section)[1].get("Metadata") or [])]
    parent_c17a1 = get(base, "/library/metadata/%s" % show)[1]["Metadata"][0]
    stamped_c17a1 = [r_c17a1 for r_c17a1 in leaves_c17a1
                     if str(r_c17a1.get("grandparentThumb") or "")
                     .endswith("/%s" % r_c17a1.get("addedAt"))]
    art_c17a1 = [r_c17a1 for r_c17a1 in leaves_c17a1
                 if str(r_c17a1.get("art") or "").endswith("/%s" % r_c17a1.get("addedAt"))]
    current_c17a1 = [r_c17a1 for r_c17a1 in grid_c17a1
                     if r_c17a1.get("grandparentThumb") == parent_c17a1.get("thumb")]
    # By this point the suite has deleted and re-picked the show's artwork several
    # times and given individual episodes artwork of their own, so the check is stated
    # over the paths that are still BORROWED -- the ones naming the show -- rather than
    # over every row. That is the half that distinguishes the two containers: on
    # /allLeaves a borrowed path carries the leaf's own `addedAt`, and everywhere else
    # it carries the show's current version.
    def borrowed_c17a1(rows_c17a1):
        out_c17a1 = []
        for row_c17a1 in rows_c17a1:
            for field_c17a1 in ("grandparentThumb", "grandparentArt", "art"):
                value_c17a1 = str(row_c17a1.get(field_c17a1) or "")
                if value_c17a1.startswith("/library/metadata/%s/" % show):
                    out_c17a1.append((value_c17a1, row_c17a1.get("addedAt")))
        return out_c17a1
    leaf_paths_c17a1 = borrowed_c17a1(leaves_c17a1)
    grid_paths_c17a1 = borrowed_c17a1(grid_c17a1)
    # Cycle 20 made an artwork version the OWNING row's `updatedAt`, so "ends with the
    # leaf's addedAt" can be true by coincidence. What distinguishes the two containers
    # without depending on those numbers: on /allLeaves each borrowed path carries its
    # OWN leaf's stamp, and on every other container they all carry the SAME one.
    grid_versions_c17a1 = {value_c17a1.rsplit("/", 1)[-1]
                           for value_c17a1, _added_c17a1 in grid_paths_c17a1}
    leaf_versions_c17a1 = {value_c17a1.rsplit("/", 1)[-1]
                           for value_c17a1, _added_c17a1 in leaf_paths_c17a1}
    check("a show's allLeaves stamps the grandparent artwork with the leaf's addedAt",
          bool(leaf_paths_c17a1)
          and all(value_c17a1.endswith("/%s" % added_c17a1)
                  for value_c17a1, added_c17a1 in leaf_paths_c17a1)
          and bool(grid_paths_c17a1) and len(grid_versions_c17a1) == 1
          and len(leaf_versions_c17a1) > 1,
          "allLeaves borrowed=%d stamps=%s; grid borrowed=%d stamps=%s"
          % (len(leaf_paths_c17a1), sorted(leaf_versions_c17a1),
             len(grid_paths_c17a1), sorted(grid_versions_c17a1)))


    # Cycle 17, derived by the driver from kids (1.43.4) and zen (1.42.2) and verified
    # against both: a ROW's XML attribute order. Cycle 16 settled the CONTAINER's and
    # left a row's explicitly unmapped for this cycle. It is not alphabetical and not
    # the order the row dict was built in: a tag is `id, filter, tag`, a movie leads
    # `ratingKey, key, guid, slug, studio, type, title, titleSort`, and a Hub leads
    # `hubKey, key, title, type, hubIdentifier`. 25 element buckets, each a topological
    # sort of every attribute PAIR the two references were seen to emit and each checked
    # to be a superset of every observed sequence; plexsim inverted a witnessed pair in
    # 11 of them, 634 pairs in all.
    #
    # What it costs a real client: nothing visible -- every Plex client uses a real XML
    # parser, and attribute order is invisible to one. It is fixed because the corpus
    # replay in harness/scripts compares attribute presence and values but not order, so
    # nothing else in the programme would ever catch it, and because a recorded corpus
    # cannot be matched byte for byte while it is wrong.
    def attrs_c17a2(path_c17a2, element_c17a2):
        body_c17a2 = request(base, "GET", path_c17a2, want_json=False)[1].decode(
            "utf-8", "replace")
        found_c17a2 = re.search(r"<%s ([^>]*?)/?>" % element_c17a2, body_c17a2)
        return ([m_c17a2.group(1) for m_c17a2
                 in re.finditer(r'(\w+)="', found_c17a2.group(1))] if found_c17a2 else [])
    movie_attrs_c17a2 = attrs_c17a2("/library/sections/%s/all" % movie_section, "Video")
    genre_attrs_c17a2 = attrs_c17a2("/library/metadata/%s" % movie, "Genre")
    section_attrs_c17a2 = attrs_c17a2("/library/sections", "Directory")

    def leads_c17a2(got_c17a2, want_c17a2):
        present_c17a2 = [n_c17a2 for n_c17a2 in want_c17a2 if n_c17a2 in got_c17a2]
        return [n_c17a2 for n_c17a2 in got_c17a2
                if n_c17a2 in present_c17a2] == present_c17a2
    # The Genre half runs on whatever tag list the row still has: by this point the
    # suite has replaced and cleared every tag list, so it is asserted only when a
    # Genre row is actually emitted.
    check("a row's XML attributes come out in the measured order",
          leads_c17a2(movie_attrs_c17a2,
                      ["ratingKey", "key", "guid", "slug", "studio", "type", "title",
                       "titleSort", "librarySectionTitle", "librarySectionID",
                       "librarySectionKey", "summary", "year", "thumb", "art",
                       "duration", "addedAt", "updatedAt"])
          and (not genre_attrs_c17a2 or genre_attrs_c17a2[:3] == ["id", "filter", "tag"])
          and leads_c17a2(section_attrs_c17a2,
                          ["allowSync", "filters", "refreshing", "key", "type", "title",
                           "agent", "scanner", "language", "uuid", "updatedAt",
                           "createdAt", "scannedAt", "content", "directory",
                           "contentChangedAt", "hidden"]),
          "movie=%s genre=%s section=%s"
          % (movie_attrs_c17a2[:6], genre_attrs_c17a2[:3], section_attrs_c17a2[:5]))


    # Cycle 17, second pass over the row attribute order: the untyped `Directory` rows.
    # The first table's one untyped order came from the "All episodes" row alone, so it
    # put `key, title` ahead of everything. Measured on kids and zen, which agree: a
    # SORT row is `default, defaultDirection, descKey, firstCharacterKey, key, title`, a
    # `firstCharacter` bucket is `size, key, title`, a FILTER row is `filter,
    # filterType, key, title, type` and the All-episodes row is `leafCount, thumb,
    # viewedLeafCount, key, title`. All four agree on `key` before `title`, so one union
    # order serves them: the shape-specific attributes never co-occur.
    def first_attrs_c17a3(path_c17a3):
        body_c17a3 = request(base, "GET", path_c17a3, want_json=False)[1].decode(
            "utf-8", "replace")
        found_c17a3 = re.search(r"<Directory ([^>]*?)/?>", body_c17a3)
        return ([m_c17a3.group(1) for m_c17a3
                 in re.finditer(r'(\w+)="', found_c17a3.group(1))] if found_c17a3 else [])
    sorts_c17a3 = first_attrs_c17a3("/library/sections/%s/sorts" % movie_section)
    chars_c17a3 = first_attrs_c17a3("/library/sections/%s/firstCharacter" % movie_section)
    filters_c17a3 = first_attrs_c17a3("/library/sections/%s/filters" % movie_section)
    check("the untyped Directory rows order their attributes too",
          sorts_c17a3[:2] == ["default", "defaultDirection"]
          and sorts_c17a3[-2:] == ["key", "title"]
          and chars_c17a3 == ["size", "key", "title"]
          and filters_c17a3[:2] == ["filter", "filterType"],
          "sorts=%s firstCharacter=%s filters=%s"
          % (sorts_c17a3[:4], chars_c17a3, filters_c17a3[:3]))


    # Cycle 17, measured on kids (1.43.4) and zen (1.42.2) over the bare path and every
    # `mediaType=`: `tv.plex.agents.nfo.movie` and `tv.plex.agents.nfo.series` exist on
    # 1.43.4 and on NOTHING on 1.42.2, which lists four modern agents where 1.43.4 lists
    # six. `system_agents.json` was captured off kids, so plexsim -- which reports
    # 1.42.2 -- offered the Add Library and Edit Library dialogs an agent a server of
    # its version does not have; picking it is a scanner/agent pair a real 1.42.2 would
    # refuse. Same family as this cycle's Meta Field split: a fixture captured off the
    # wrong version. The three legacy `com.plexapp.agents.*` rows both references also
    # list stay deliberately absent -- plexsim hosts no plug-in framework, and that is
    # recorded in the fixture's own provenance.
    def agents_c17d6(query_c17d6):
        return [a_c17d6.get("identifier") for a_c17d6
                in (get(base, "/system/agents%s" % query_c17d6)[1].get("Agent") or [])]
    bare_c17d6 = agents_c17d6("")
    movie_c17d6 = agents_c17d6("?mediaType=1")
    show_c17d6 = agents_c17d6("?mediaType=2")
    check("the NFO agents are 1.43.4's and not 1.42.2's",
          not [a_c17d6 for a_c17d6 in bare_c17d6 if "nfo" in str(a_c17d6)]
          and bare_c17d6 == ["tv.plex.agents.movie", "tv.plex.agents.series",
                             "tv.plex.agents.music", "tv.plex.agents.none"]
          and movie_c17d6 == ["tv.plex.agents.movie", "tv.plex.agents.none"]
          and show_c17d6 == ["tv.plex.agents.series", "tv.plex.agents.none"],
          "bare=%s movie=%s show=%s" % (bare_c17d6, movie_c17d6, show_c17d6))


    # Cycle 17, re-measured by the driver on plexscratch character by character and
    # corroborated on zen: a leading run of PUNCTUATION comes off the sort title, and it
    # comes off BEFORE the article. zen's episode 10866 is titled "'Til Death Do Us Art"
    # and sorts as "Til Death Do Us Art"; its episode `firstCharacter` axis has 27
    # buckets -- `#` then A-Z, no apostrophe bucket -- and the `T` bucket holds that row.
    # The set is not a Unicode category: in ASCII only `" ' ( - . [ {` and `~` strip
    # while `! # $ % & ) * + , / : ; < = > ? @ \ ] ^ _ ` | }` do not, and the fullwidth
    # and CJK brackets do not either. Everything from U+0080 to U+00BF and everything
    # from U+2000 to U+2FFF does strip -- 85 of 85 characters tested across those ranges
    # -- while U+0100..U+1FFF and U+3000 upwards do not, so the boundary is sharp on
    # both sides. The run may mix those characters with whitespace and repeat, and a
    # title made of nothing else keeps its own text rather than sorting as the empty
    # string.
    live_c17a4 = [r_c17a4["ratingKey"] for r_c17a4
                  in (get(base, "/library/sections/%s/all" % movie_section)[1]
                      .get("Metadata") or [])]
    subject_c17a4 = live_c17a4[-1] if live_c17a4 else None

    def sort_of_c17a4(title_c17a4):
        request(base, "PUT", "/library/metadata/%s?type=1&id=%s&title.value=%s"
                             "&title.locked=1"
                % (subject_c17a4, subject_c17a4, quote(title_c17a4)))
        rows_c17a4 = get(base, "/library/metadata/%s"
                         % subject_c17a4)[1].get("Metadata") or [{}]
        return rows_c17a4[0].get("title"), rows_c17a4[0].get("titleSort")
    if not subject_c17a4:
        skip("a leading punctuation run comes off the sort title",
             "the fixture has no movie left")
    else:
        cases_c17a4 = [
            ("'Til Death Do Us Art", "Til Death Do Us Art"),
            ("(Krishna Katha) Pootna", "Krishna Katha) Pootna"),
            ("-The Zulu Probe", "Zulu Probe"),
            ("((( Zulu Probe", "Zulu Probe"),
            (" . - Zulu Probe", "Zulu Probe"),
            ("\u2018Zulu Probe", "Zulu Probe"),
            ("\u00a1Zulu Probe", "Zulu Probe"),
            # the article comes off AFTER the run, and only once, so a bracket that
            # follows the article stays
            ("The (Zulu Probe", "(Zulu Probe"),
            # kept: these are not in the set
            (")Zulu Probe", None),
            ("!Zulu Probe", None),
            ("\uff08Zulu Probe", None),
            # a title with nothing but strippable characters keeps its own text
            ("(((", None),
        ]
        wrong_c17a4 = []
        for title_c17a4, want_c17a4 in cases_c17a4:
            got_title_c17a4, got_c17a4 = sort_of_c17a4(title_c17a4)
            if got_title_c17a4 != title_c17a4 or got_c17a4 != want_c17a4:
                wrong_c17a4.append((title_c17a4, got_c17a4, want_c17a4))
        check("a leading punctuation run comes off the sort title",
              not wrong_c17a4, "wrong=%s" % wrong_c17a4[:3])


    # Cycle 17, re-measured by the driver on plexscratch: a save a real PMS REFUSES
    # writes nothing at all. `PUT /library/metadata/{id}?title.value=PARTIAL&
    # year.value=abc` is a 500 there and the title is untouched. plexsim applied each
    # parameter as it validated it, so everything before the bad one landed and
    # everything after it did not -- the client is told the save failed, keeps its old
    # model, and the row on disk has moved. The same on the section save path.
    original_c17b1 = get(base, "/library/metadata/%s" % show)[1]["Metadata"][0]["title"]
    request(base, "PUT", "/library/metadata/%s?title.value=HALF&year.value=abc" % show)
    after_item_c17b1 = get(base, "/library/metadata/%s" % show)[1]["Metadata"][0]["title"]
    request(base, "PUT", "/library/sections/%s/all?type=2&id=%s&title.value=HALF"
                         "&zzzUnknown.value=1" % (show_section, show))
    after_section_c17b1 = get(base, "/library/metadata/%s"
                              % show)[1]["Metadata"][0]["title"]
    check("a refused save writes nothing",
          after_item_c17b1 == original_c17b1
          and after_section_c17b1 == original_c17b1,
          "before=%r after-item=%r after-section=%r"
          % (original_c17b1, after_item_c17b1, after_section_c17b1))


    # Cycle 17, re-measured on plexscratch: the ITEM edit path's 400 means "this
    # request edits nothing", not "an unknown field". With a real edit beside it the
    # reference IGNORES every name it does not recognise -- an unknown `.value`, a bare
    # unknown name, an unknown TAG type and an option like `flattenSeasons=1` all
    # answer 200 and the edit lands. Each of them ALONE is still a 400, as is a PUT
    # with no parameters. The recorded rule ("an unknown field or tag type is 400") was
    # measured with the unknown name alone, which is failure class A: the client sends
    # its save with whatever options it carries, and plexsim 400'd 34 of the 71 names
    # swept -- so a client that appends one option plexsim does not know loses the
    # whole save.
    def edit_c17b2(query_c17b2):
        request(base, "PUT", "/library/metadata/%s?title.value=SENTINEL17" % show)
        status_c17b2, _, _ = request(base, "PUT", "/library/metadata/%s%s"
                                     % (show, query_c17b2))
        return status_c17b2, get(base, "/library/metadata/%s"
                                 % show)[1]["Metadata"][0].get("title")
    with_unknown_c17b2 = edit_c17b2("?title.value=EDITED17&zzzUnknown.value=1")
    with_bare_c17b2 = edit_c17b2("?title.value=EDITED17&zzzUnknown=1")
    with_option_c17b2 = edit_c17b2("?title.value=EDITED17&flattenSeasons=1")
    with_tag_c17b2 = edit_c17b2("?title.value=EDITED17&zzztag[0].tag.tag=x")
    alone_c17b2 = edit_c17b2("?zzzUnknown=1")
    option_alone_c17b2 = edit_c17b2("?flattenSeasons=1")
    bare_c17b2 = edit_c17b2("")
    check("the item edit path ignores a name it does not know",
          with_unknown_c17b2 == (200, "EDITED17")
          and with_bare_c17b2 == (200, "EDITED17")
          and with_option_c17b2 == (200, "EDITED17")
          and with_tag_c17b2 == (200, "EDITED17")
          and alone_c17b2 == (400, "SENTINEL17")
          and option_alone_c17b2 == (400, "SENTINEL17")
          and bare_c17b2 == (400, "SENTINEL17"),
          "unknown=%s bare=%s option=%s tag=%s alone=%s/%s/%s"
          % (with_unknown_c17b2, with_bare_c17b2, with_option_c17b2, with_tag_c17b2,
             alone_c17b2, option_alone_c17b2, bare_c17b2))


    # Cycle 17, re-measured on plexscratch: on the SECTION save path a form that names
    # nothing to write is a 200 that edits nothing, not a 400 -- `?type=2&id={id}` on
    # its own, with a bare unknown name, with `includeGuids=1` or with
    # `flattenSeasons=1` are all 200s there, because on that path a bare `field=value`
    # is a FILTER and a filter that matches nothing to write is simply a no-op. The
    # unknown `.value` form stays a 400 on this path, which is the one place the two
    # paths genuinely differ (the item path ignores it -- see the check above).
    def section_c17b3(query_c17b3):
        status_c17b3, _, _ = request(
            base, "PUT", "/library/sections/%s/all?type=2&id=%s%s"
            % (show_section, show, query_c17b3))
        return status_c17b3
    check("a section save with nothing to write is a 200",
          section_c17b3("") == 200 and section_c17b3("&zzzUnknown=1") == 200
          and section_c17b3("&includeGuids=1") == 200
          and section_c17b3("&flattenSeasons=1") == 200
          and section_c17b3("&zzzUnknown.value=1") == 400,
          "bare=%s unknown=%s include=%s flatten=%s dotvalue=%s"
          % (section_c17b3(""), section_c17b3("&zzzUnknown=1"),
             section_c17b3("&includeGuids=1"), section_c17b3("&flattenSeasons=1"),
             section_c17b3("&zzzUnknown.value=1")))


    # Cycle 17, re-measured by the driver on plexscratch: the collection ITEM paths
    # answer 404 to every verb they do not implement. `/library/collections/{id}/items`
    # takes PUT (add) and nothing else; `/items/{ratingKey}` takes DELETE and nothing
    # else; `/items/{ratingKey}/move` takes PUT and nothing else. plexsim answered 200
    # with an empty container to POST, DELETE, PATCH and OPTIONS on the list, 200 with
    # an INVENTED single-item container to a GET of one member, and 200 with the whole
    # children listing to a GET of `/move` -- fix 4's trap from the inside, where a
    # client reads any 200 as "this endpoint exists".
    made_c17b4 = json.loads(request(
        base, "POST", "/library/collections?type=1&title=c17verbs&smart=0&sectionId=%s"
                      "&uri=%s"
        % (movie_section,
           quote("server://%s/com.plexapp.plugins.library/library/metadata/%s"
                 % (machine, movie))))[1])
    collection_c17b4 = (made_c17b4["MediaContainer"]["Metadata"][0]["ratingKey"]
                        if (made_c17b4.get("MediaContainer") or {}).get("Metadata")
                        else None)
    if not collection_c17b4:
        skip("the collection item paths 404 the verbs they do not implement",
             "could not build a collection")
    else:
        refused_c17b4 = []
        for path_c17b4, verbs_c17b4 in (
                ("/library/collections/%s/items" % collection_c17b4,
                 # Cycle 31: PATCH is out of every verb list in the suite -- on 1.42.2 it
                 # is not a method at all (a 500 on every path), asserted on its own.
                 ("POST", "DELETE", "OPTIONS")),
                ("/library/collections/%s/items/%s" % (collection_c17b4, movie),
                 ("GET", "POST", "OPTIONS", "HEAD")),
                ("/library/collections/%s/items/%s/move" % (collection_c17b4, movie),
                 ("GET", "POST", "DELETE", "OPTIONS"))):
            for verb_c17b4 in verbs_c17b4:
                status_c17b4, _, _ = request(base, verb_c17b4, path_c17b4)
                if status_c17b4 != 404:
                    refused_c17b4.append((verb_c17b4, path_c17b4.split("/")[-1],
                                          status_c17b4))
        still_c17b4, _, _ = request(
            base, "PUT", "/library/collections/%s/items?uri=%s"
            % (collection_c17b4,
               quote("server://%s/com.plexapp.plugins.library/library/metadata/%s"
                     % (machine, movie))))
        check("the collection item paths 404 the verbs they do not implement",
              not refused_c17b4 and still_c17b4 == 200,
              "not-404=%s; the PUT still adds: %s" % (refused_c17b4[:4], still_c17b4))
        request(base, "DELETE", "/library/collections/%s" % collection_c17b4)


    # Cycle 17, re-measured on plexscratch: `POST` on an item ACTION leaf is a 404 --
    # `/refresh`, `/analyze` and `/unmatch` all take PUT and refuse POST, where
    # `POST /library/sections/{id}/refresh` really is a 200. And `/library/metadata/
    # {id}/match` answers EVERY verb with its own no-parameters refusal: a GET and a
    # DELETE there are 400, not 404. plexsim ran the action on a POST -- so a client
    # that got the verb wrong re-matched an item instead of being refused -- and 404'd
    # the two match reads.
    post_c17b5 = {}
    for leaf_c17b5 in ("refresh", "analyze", "unmatch"):
        post_c17b5[leaf_c17b5] = request(
            base, "POST", "/library/metadata/%s/%s" % (movie, leaf_c17b5))[0]
    section_c17b5 = request(base, "POST", "/library/sections/%s/refresh"
                            % movie_section)[0]
    match_c17b5 = [request(base, verb_c17b5, "/library/metadata/%s/match" % movie)[0]
                   for verb_c17b5 in ("GET", "DELETE")]
    check("POST on an item action leaf is a 404, and a match read is a 400",
          set(post_c17b5.values()) == {404} and section_c17b5 == 200
          and match_c17b5 == [400, 400],
          "post=%s section=%s match=%s" % (post_c17b5, section_c17b5, match_c17b5))


    # Cycle 17, re-measured on plexscratch: `GET /library/sections/{id}/refresh?force=`
    # PARSES the flag -- `abc` and an empty value are 400s there, where `0` and `1` are
    # 200s. plexsim took anything and ran the scan, so a client that sent a malformed
    # flag triggered a full refresh instead of being refused.
    force_c17b6 = {value_c17b6: request(
        base, "GET", "/library/sections/%s/refresh?force=%s"
        % (movie_section, value_c17b6))[0]
        for value_c17b6 in ("0", "1", "abc", "", "1.5", "-1")}
    check("a section refresh parses its force flag",
          force_c17b6["0"] == 200 and force_c17b6["1"] == 200
          and force_c17b6["abc"] == 400 and force_c17b6[""] == 400
          and force_c17b6["1.5"] == 400,
          "%s" % force_c17b6)


    # Cycle 17, re-measured on plexscratch: a KNOWN single-segment path falls through
    # to the legacy plug-in dispatcher for the verbs it does not implement. `PUT`,
    # `PATCH` and `OPTIONS` on `/butler` and on `/devices` answer the dispatcher's
    # `{"size": 0, "content": "plugins"}`, exactly as an unknown single-segment path
    # does -- the recorded rule that a read-only route 404s every verb but GET and HEAD
    # is the rule for MULTI-segment routes. plexsim 404'd them.
    fell_c17b7 = {}
    for path_c17b7 in ("/butler", "/devices"):
        for verb_c17b7 in ("PUT", "OPTIONS"):   # cycle 31: PATCH is a 500 on 1.42.2
            status_c17b7, body_c17b7, _ = request(base, verb_c17b7, path_c17b7)
            fell_c17b7[(path_c17b7, verb_c17b7)] = (
                status_c17b7, b"plugins" in body_c17b7)
    check("a known single-segment path falls through to the plug-in dispatcher",
          all(value_c17b7 == (200, True) for value_c17b7 in fell_c17b7.values()),
          "%s" % sorted((k_c17b7[0] + " " + k_c17b7[1], v_c17b7)
                        for k_c17b7, v_c17b7 in fell_c17b7.items())[:4])


    # Cycle 17, measured read-only on kids (1.43.4) and zen (1.42.2), which agree
    # exactly: `GET /livetv` is the plug-in dispatcher's own THREE-row container --
    # `dvrs`, `epg`, `sessions`, with `content="plugins"` -- not an empty one. plexsim
    # routed the whole `/livetv` tree to a bare empty container, so the one path that
    # does answer said the server had no Live TV surface at all rather than no tuner.
    status_c17b8, livetv_c17b8, _ = get(base, "/livetv")
    rows_c17b8 = [d_c17b8.get("key") for d_c17b8 in (livetv_c17b8.get("Directory") or [])]
    check("GET /livetv is the plug-in dispatcher's three-row container",
          status_c17b8 == 200 and rows_c17b8 == ["dvrs", "epg", "sessions"]
          and livetv_c17b8.get("content") == "plugins"
          and livetv_c17b8.get("size") == 3,
          "size=%s content=%r rows=%s" % (livetv_c17b8.get("size"),
                                          livetv_c17b8.get("content"), rows_c17b8))


    # Cycle 17, re-measured by the driver on plexscratch: a library PREFERENCE write
    # moves the section's own `updatedAt`. plexsim left it where it was, and clients
    # cache a library keyed on that stamp -- so a settings change never invalidated the
    # cache. The write itself is unchanged: 200 with an empty body and zero frames on
    # both, exactly as cycle 15 recorded.
    before_c17b9 = {d_c17b9["key"]: d_c17b9.get("updatedAt") for d_c17b9
                    in (get(base, "/library/sections")[1].get("Directory") or [])}
    status_c17b9, body_c17b9, _ = request(
        base, "PUT", "/library/sections/%s/prefs?enableCinemaTrailers=0" % movie_section)
    after_c17b9 = {d_c17b9["key"]: d_c17b9.get("updatedAt") for d_c17b9
                   in (get(base, "/library/sections")[1].get("Directory") or [])}
    other_c17b9 = [key_c17b9 for key_c17b9 in before_c17b9
                   if key_c17b9 != str(movie_section)
                   and before_c17b9[key_c17b9] != after_c17b9.get(key_c17b9)]
    check("a library preference write moves the section's updatedAt",
          status_c17b9 == 200 and body_c17b9 == b""
          and before_c17b9.get(str(movie_section)) != after_c17b9.get(str(movie_section))
          and after_c17b9.get(str(movie_section)) is not None
          and not other_c17b9,
          "%s -> %s (other sections moved: %s)"
          % (before_c17b9.get(str(movie_section)), after_c17b9.get(str(movie_section)),
             other_c17b9))


    # Cycle 17, re-measured on plexscratch: an INT library preference whose value does
    # not parse is stored as **0**, not ignored. `abc`, an empty value, `1.5`, a space
    # and `0x3` all read back as `0` where `007` reads back as `7`. This corrects the
    # recorded rule -- "a bad int is a 500 on /:/prefs, IGNORED on a library" -- whose
    # second half was measured by watching the write answer 200 without reading the
    # value back. Clearing "Minimum automatic collection size" in the Edit Library
    # dialog is exactly this request, and on plexsim it silently kept the old number.
    def threshold_c17b10():
        for s_c17b10 in (get(base, "/library/sections/%s/prefs"
                             % movie_section)[1].get("Setting") or []):
            if s_c17b10.get("id") == "autoCollectionThreshold":
                return s_c17b10.get("value")
        return None
    read_c17b10 = {}
    for value_c17b10 in ("abc", "", "1.5", "0x3", "007"):
        request(base, "PUT", "/library/sections/%s/prefs?autoCollectionThreshold=7"
                % movie_section)
        request(base, "PUT", "/library/sections/%s/prefs?autoCollectionThreshold=%s"
                % (movie_section, quote(value_c17b10)))
        read_c17b10[value_c17b10] = threshold_c17b10()
    check("an int library preference that does not parse is stored as 0",
          read_c17b10["abc"] == "0" and read_c17b10[""] == "0"
          and read_c17b10["1.5"] == "0" and read_c17b10["0x3"] == "0"
          and read_c17b10["007"] == "7",
          "%s" % read_c17b10)


    # Cycle 17, re-measured on plexscratch: a library TEXT preference is stored
    # percent-ESCAPED for the two characters that delimit an `enumValues` string --
    # `:` becomes `%3a` and `|` becomes `%7c`, in lowercase hex -- and a value carrying
    # a `%` of its own is stored EMPTY. Every other character round-trips, `/` and a
    # space included. The server is protecting its own encoding; plexsim stored all
    # three verbatim.
    def country_c17b11():
        for s_c17b11 in (get(base, "/library/sections/%s/prefs"
                             % movie_section)[1].get("Setting") or []):
            if s_c17b11.get("id") == "country":
                return s_c17b11.get("value")
        return None
    original_c17b11 = country_c17b11()
    stored_c17b11 = {}
    for value_c17b11 in ("x:y", "x|y", "x%y", "x/y", "x y"):
        request(base, "PUT", "/library/sections/%s/prefs?country=%s"
                % (movie_section, quote(value_c17b11)))
        stored_c17b11[value_c17b11] = country_c17b11()
    if original_c17b11 is not None:
        request(base, "PUT", "/library/sections/%s/prefs?country=%s"
                % (movie_section, quote(original_c17b11)))
    check("a library text preference escapes the enum delimiters",
          stored_c17b11["x:y"] == "x%3ay" and stored_c17b11["x|y"] == "x%7cy"
          and stored_c17b11["x%y"] == "" and stored_c17b11["x/y"] == "x/y"
          and stored_c17b11["x y"] == "x y",
          "%s" % stored_c17b11)


    # Cycle 17, re-measured by the driver on kids (1.43.4) AND zen (1.42.2), which agree
    # over 13 and 97 candidates: an artwork candidate whose `ratingKey` is a LOCAL uri
    # -- `metadata://`, `media://`, `upload://` -- carries that bare uri as its
    # `ratingKey` and a SERVER PATH as its `key` and `thumb`:
    # `/library/metadata/{id}/file?url=<the uri percent-encoded, with `.` encoded too>`,
    # which really serves the image (200 image/jpeg on kids). A `media://` candidate
    # carries NO `provider` while a `metadata://` one carries the agent's. plexsim put
    # the bare uri in `key` and `thumb` and stamped every local row `provider: "local"`,
    # so Change Artwork drew each uploaded tile with `img src="upload://posters/..."`,
    # which no browser can fetch -- a grid of broken tiles.
    posted_c17b12, _, _ = request(
        base, "POST", "/library/metadata/%s/posters" % movie,
        body=b"\x89PNG\r\n\x1a\n" + b"\x00" * 24)
    cands_c17b12 = (get(base, "/library/metadata/%s/posters" % movie)[1]
                    .get("Metadata") or [])
    local_c17b12 = [r_c17b12 for r_c17b12 in cands_c17b12
                    if "://" in str(r_c17b12.get("ratingKey") or "")
                    and not str(r_c17b12.get("ratingKey")).startswith("http")]
    shaped_c17b12 = [r_c17b12 for r_c17b12 in local_c17b12
                     if str(r_c17b12.get("key") or "").startswith(
                         "/library/metadata/%s/file?url=" % movie)
                     and r_c17b12.get("key") == r_c17b12.get("thumb")
                     and "%3A%2F%2F" in r_c17b12.get("key", "")
                     and "provider" not in r_c17b12]
    served_c17b12 = (request(base, "GET", local_c17b12[0]["key"], want_json=False)[0]
                     if local_c17b12 else None)
    # The dot escaping has no witness in an upload uri, which carries none, so it is
    # asserted directly against the reference's own encoding of one that does.
    dotted_c17b12 = json.loads(request(
        base, "GET", "/library/metadata/%s/file?url=%s"
        % (movie, quote("metadata://posters/tv.plex.agents.movie_x")
           .replace(".", "%2E")), want_json=False)[1][:0] or b"null")
    check("a local artwork candidate names a server path, not its uri",
          bool(local_c17b12) and len(shaped_c17b12) == len(local_c17b12)
          and served_c17b12 == 200 and dotted_c17b12 is None,
          "local=%d shaped=%d served=%s key=%r"
          % (len(local_c17b12), len(shaped_c17b12), served_c17b12,
             (local_c17b12[0].get("key") if local_c17b12 else None)))


    # Cycle 17, re-measured on plexscratch: `DELETE /library/metadata/{id}/thumb` really
    # CLEARS the poster -- the field goes and the row's other artwork is re-stamped,
    # exactly as `/poster` and `/art` already did.
    #
    # Cycle 31: that is **1.43.4's** answer. On 1.42.2 -- the build plexsim reports -- all
    # five artwork DELETE leaves are 404s, so this check now drives the clear through the
    # empty-value edit, which both versions answer identically. The rule being tested is
    # the same one: clearing a poster removes the field and 404s the bare path.
    request(base, "POST", "/library/metadata/%s/posters" % movie,
            body=b"\x89PNG\r\n\x1a\n" + b"\x00" * 24)
    before_c17b13 = get(base, "/library/metadata/%s" % movie)[1]["Metadata"][0]
    status_c17b13, body_c17b13, _ = request(
        base, "PUT", "/library/metadata/%s?thumb.value=" % movie)
    after_c17b13 = get(base, "/library/metadata/%s" % movie)[1]["Metadata"][0]
    bare_c17b13, _, _ = request(base, "GET", "/library/metadata/%s/thumb" % movie,
                                want_json=False)
    check("the empty-value edit on thumb clears the poster",
          status_c17b13 == 200 and body_c17b13 == b""
          and before_c17b13.get("thumb") and "thumb" not in after_c17b13
          and bare_c17b13 == 404,
          "%s body=%r %r -> %r ; bare GET %s"
          % (status_c17b13, body_c17b13, before_c17b13.get("thumb"),
             after_c17b13.get("thumb"), bare_c17b13))


    # Cycle 17, re-measured on plexscratch: an artwork UPLOAD moves `updatedAt` onto the
    # same stamp the new artwork path carries, exactly as an artwork PICK does. Cycle 15
    # measured that for the pick and plexsim implemented it there only, so a client that
    # caches on `updatedAt` -- which is what the stamp is for -- never refetched a poster
    # the user had just uploaded.
    before_c17b14 = get(base, "/library/metadata/%s" % movie)[1]["Metadata"][0]
    request(base, "POST", "/library/metadata/%s/posters" % movie,
            body=b"\x89PNG\r\n\x1a\n" + b"\x00" * 24)
    after_c17b14 = get(base, "/library/metadata/%s" % movie)[1]["Metadata"][0]
    stamp_c17b14 = str(after_c17b14.get("thumb") or "").rsplit("/", 1)[-1]
    check("an artwork upload moves updatedAt onto the new stamp",
          after_c17b14.get("thumb") != before_c17b14.get("thumb")
          and stamp_c17b14.isdigit()
          and str(after_c17b14.get("updatedAt")) == stamp_c17b14,
          "thumb=%r updatedAt %s -> %s"
          % (after_c17b14.get("thumb"), before_c17b14.get("updatedAt"),
             after_c17b14.get("updatedAt")))


    # Cycle 17, re-measured by the driver on plexscratch: a collection's children on the
    # METADATA path answer the LIGHT grid row inside a container that carries the
    # librarySection triple and `allowSync: true` and NO `thumb`. plexsim sent the full
    # detail row -- `Guid`, `Rating`, every tag list with ids, the whole `Stream` table
    # -- put the librarySection triple on each ROW instead of the container, said
    # `allowSync: false`, and added a `thumb` the reference does not carry. A client
    # reading the library off the container got nothing, a mobile client was told the
    # collection cannot be synced, and every member shipped its stream list.
    made_c17b15 = json.loads(request(
        base, "POST", "/library/collections?type=1&title=c17rows&smart=0&sectionId=%s"
                      "&uri=%s"
        % (movie_section,
           quote("server://%s/com.plexapp.plugins.library/library/metadata/%s"
                 % (machine, movie))))[1])
    cid_c17b15 = (made_c17b15["MediaContainer"]["Metadata"][0]["ratingKey"]
                  if (made_c17b15.get("MediaContainer") or {}).get("Metadata") else None)
    if not cid_c17b15:
        skip("a collection's metadata children are the light row", "no collection")
    else:
        _, kids_c17b15, _ = get(base, "/library/metadata/%s/children" % cid_c17b15)
        row_c17b15 = (kids_c17b15.get("Metadata") or [{}])[0]
        streams_c17b15 = any("Stream" in part_c17b15
                             for media_c17b15 in (row_c17b15.get("Media") or [])
                             for part_c17b15 in (media_c17b15.get("Part") or []))
        check("a collection's metadata children are the light row",
              kids_c17b15.get("allowSync") is True
              and kids_c17b15.get("librarySectionID") is not None
              and kids_c17b15.get("librarySectionTitle")
              and kids_c17b15.get("librarySectionUUID")
              and "thumb" not in kids_c17b15
              and "Guid" not in row_c17b15 and "Rating" not in row_c17b15
              and not streams_c17b15
              and "librarySectionID" not in row_c17b15,
              "allowSync=%r sectionID=%r thumb=%s row: Guid=%s Rating=%s Stream=%s "
              "triple=%s" % (kids_c17b15.get("allowSync"),
                             kids_c17b15.get("librarySectionID"),
                             "thumb" in kids_c17b15, "Guid" in row_c17b15,
                             "Rating" in row_c17b15, streams_c17b15,
                             "librarySectionID" in row_c17b15))
        request(base, "DELETE", "/library/collections/%s" % cid_c17b15)


    # Cycle 17: the verb table above must not take the member LIST's own read with it.
    # `GET /library/collections/{id}/items` is the member list -- recorded since cycle
    # 14 and measured again here -- while a GET of ONE member and of `/move` really are
    # 404s on the reference. The refusals the reference was measured on were POST,
